insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-pe-168","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The size order Li⁺ > Be²⁺ > B³⁺ holds because","options":["electron count rises along the series","nuclear charge rises while the electron count stays two","a new shell is added at each step","these ions are not isoelectronic"],"answer_index":1,"explanation":"All three are 1s² species; higher Z pulls the same two electrons closer.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius"},{"id":"che-pe-169","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Zirconium and hafnium have nearly identical atomic radii because of","options":["alkali-metal contraction","lanthanoid contraction","an extra 4s shell on Hf","a fall in Z from Zr to Hf"],"answer_index":1,"explanation":"The 14 poorly shielding 4f electrons inserted before Hf shrink it so that r(Hf) ≈ r(Zr).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"atomic-ionic-radius"},{"id":"che-pe-170","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fe²⁺ is larger than Fe³⁺ because removal of an extra electron","options":["adds a new shell","raises Zeff and shrinks the remaining 3d cloud","lowers the nuclear charge","converts iron into a noble gas"],"answer_index":1,"explanation":"Both ions are iron, but Fe³⁺ has fewer electrons and a higher charge density, so it is the smaller cation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"atomic-ionic-radius"},{"id":"che-pe-171","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Ionisation enthalpy is the energy needed to remove an electron from an isolated gaseous atom in its","options":["first excited state only","ground state","metallic crystal","aqueous solution"],"answer_index":1,"explanation":"The textbook definition uses the ground-state gaseous atom: M(g) → M⁺(g) + e⁻.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-172","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The first ionisation enthalpy refers to removal of an electron from the","options":["uninegative ion","neutral gaseous atom","dipositive cation","solid metal lattice"],"answer_index":1,"explanation":"IE₁ is for M(g); IE₂ is for M⁺(g), and so on.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-173","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"First ionisation enthalpy generally increases from left to right across a","options":["group","period","f-block row only","set of isotopes"],"answer_index":1,"explanation":"Zeff rises and size falls across a period, so the outer electron is harder to remove.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-174","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"First ionisation enthalpy generally decreases from top to bottom in a","options":["period","group","isoelectronic pair","triad of identical Z"],"answer_index":1,"explanation":"The valence electron is farther from the nucleus and more shielded in the heavier congener.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-175","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Ionisation enthalpies of elements are commonly expressed in","options":["kelvin","kilojoules per mole","atmospheres","cubic centimetres"],"answer_index":1,"explanation":"TSBIE tables quote ΔᵢH in kJ mol⁻¹ (sometimes also in eV per atom).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-176","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Noble gases have exceptionally high ionisation enthalpies because of their","options":["half-filled d subshells","closed-shell configurations","very large atomic radii","metallic bonding"],"answer_index":1,"explanation":"A complete ns² np⁶ (or 1s² for He) set is especially stable, so removal of an electron costs a lot of energy.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-177","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In any period the alkali metal has the","options":["highest first ionisation enthalpy","lowest first ionisation enthalpy","same IE as the noble gas","negative ionisation enthalpy"],"answer_index":1,"explanation":"The single ns¹ electron is large, weakly held and easily lost.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-178","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The second ionisation enthalpy of an element compared with its first is always","options":["smaller","larger","equal","negative"],"answer_index":1,"explanation":"The second electron is taken from a already positive ion, so IE₂ > IE₁ in every case.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-179","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metals typically have lower ionisation enthalpies than the non-metals of the","options":["same group only","same period","f-block exclusively","gaseous state only"],"answer_index":1,"explanation":"Left-hand (metallic) elements are larger and have smaller Zeff, so they lose electrons more readily.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-180","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Inner-electron screening reduces the effective nuclear charge and thereby","options":["raises ionisation enthalpy","lowers ionisation enthalpy","creates a new period","removes the nucleus"],"answer_index":1,"explanation":"A well-shielded valence electron feels less pull and is easier to remove.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-181","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A smaller atomic radius generally corresponds to a","options":["lower ionisation enthalpy","higher ionisation enthalpy","zero ionisation enthalpy","negative electron count"],"answer_index":1,"explanation":"The outer electron is closer to the nucleus and more tightly bound in a smaller atom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-182","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Successive ionisation enthalpies of an atom increase because the cation left behind","options":["holds its remaining electrons more tightly","gains a new shell","becomes electrically neutral","has a smaller nuclear charge"],"answer_index":0,"explanation":"Each removal raises the charge on the ion and shrinks the cloud, so the next IE is larger.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-183","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The process whose enthalpy change is the first ionisation enthalpy is","options":["$\\mathrm{M}^{+}(g)+e^{-}\\rightarrow \\mathrm{M}(g)$","$\\mathrm{M}(g)\\rightarrow \\mathrm{M}^{+}(g)+e^{-}$","$\\mathrm{M}(g)+e^{-}\\rightarrow \\mathrm{M}^{-}(g)$","$\\mathrm{M}(s)\\rightarrow \\mathrm{M}(g)$"],"answer_index":1,"explanation":"IE₁ is defined for the isolated gaseous atom losing one electron.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-184","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among the period-2 elements, the highest first ionisation enthalpy belongs to","options":["lithium","fluorine","neon","carbon"],"answer_index":2,"explanation":"Neon is the noble gas of that period and has the most tightly held closed-shell electrons.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy"},{"id":"che-pe-185","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Beryllium has a higher first ionisation enthalpy than boron because Be has a","options":["half-filled 2p set","filled 2s subshell","larger atomic radius than Li","vacant 1s orbital"],"answer_index":1,"explanation":"Removing an electron from stable 2s² (Be) costs more than removing the single 2p electron of B.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy"},{"id":"che-pe-186","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Nitrogen has a higher first ionisation enthalpy than oxygen because N has a","options":["filled 2s² 2p⁶ shell","half-filled 2p³ set","larger nuclear charge than O","d-orbital vacancy"],"answer_index":1,"explanation":"The extra stability of half-filled 2p³ outweighs the one-unit rise in Z from N to O.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy"},{"id":"che-pe-187","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Magnesium shows a higher first ionisation enthalpy than aluminium, an exception similar to","options":["Na versus Ar","Be versus B","F versus Ne","K versus Ca"],"answer_index":1,"explanation":"Mg (3s²) is harder to ionise than Al (3p¹), just as Be (2s²) is harder than B (2p¹).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
